"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68201"],{93975(e){e.exports=JSON.parse('{"id":"F185","slug":"flotation-adjusted-cost-of-equity","name":"Cost of New Equity with Flotation Costs","subject":"Corporate Finance","section":"Raising Capital","topic":"Seasoned equity offerings","level":"Intermediate","aliases":["seasoned equity offering cost","flotation cost","new equity issue cost"],"formula":{"latex":"r_{new}=\\\\frac{D_{1}}{P_{0}(1-f)}+g","also":[],"text":"Cost of new equity = Next dividend / (Price x (1 - flotation cost)) + Growth rate"},"symbols":[{"symbol":"r_new","meaning":"Cost of newly issued equity","unit":"per year"},{"symbol":"D_1","meaning":"Dividend expected next year","unit":"money per share"},{"symbol":"P_0","meaning":"Current share price","unit":"money per share"},{"symbol":"f","meaning":"Flotation cost as a share of the price, as a decimal","unit":"decimal"},{"symbol":"g","meaning":"Expected dividend growth","unit":"per year"}],"when_to_use":"Use it when the company raises money by selling new shares. Underwriting and issue fees reduce the proceeds, so new equity costs more than retained earnings.","worked_example":{"problem":"A share costs 40, will pay 2 next year, and dividends grow 4% a year. Issue costs are 5% of the price. What is the cost of new equity?","inputs":{"d1":2,"p0":40,"f":5,"g":4},"steps":[{"label":"Net proceeds per share = P0 x (1 - f)","working":"40 x (1-0.05)","value":"38.00"},{"label":"Cost of new equity = D1 / net proceeds + g","working":"d1 / 38+0.04","value":"9.26%"},{"label":"Without flotation costs = D1 / P0 + g","working":"d1 / 40+0.04","value":"9.00%"}],"answer":"Net proceeds are 38.00 per share, so the cost of new equity is 9.26%, compared with 9.00% for retained earnings."},"calculator":{"available":true,"inputs":[{"id":"d1","label":"Next dividend per share","unit":"money","type":"number","default":2,"hint":""},{"id":"p0","label":"Share price","unit":"money","type":"number","default":40,"hint":""},{"id":"f","label":"Flotation cost","unit":"%","type":"number","default":5,"hint":""},{"id":"g","label":"Dividend growth","unit":"%","type":"number","default":4,"hint":""}],"checks":[{"expr":"p0>0 and f<1","message":"The share price must be above zero and the flotation cost below 100%."}],"steps":[{"id":"net","label":"Net proceeds per share = P0 x (1 - f)","expr":"p0*(1-f)","format":"money"},{"id":"rnew","label":"Cost of new equity = D1 / net proceeds + g","expr":"d1/net+g","format":"pct2"},{"id":"rold","label":"Without flotation costs = D1 / P0 + g","expr":"d1/p0+g","format":"pct2"}],"results":["rnew","rold"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"rnew":0.09263157894736843,"rold":0.09}},"finder":{"finds":"Cost of raising new equity","needs":"Dividend, price, flotation cost, growth"},"related":[{"slug":"dividend-growth-cost-of-equity","name":"Cost of Equity (Dividend Growth)"},{"slug":"wacc","name":"Weighted Average Cost of Capital (WACC)"}],"related_ids":["F162","F165"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>r</mi><mrow><mi>n</mi><mi>e</mi><mi>w</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>D</mi><mn>1</mn></msub><mrow><msub><mi>P</mi><mn>0</mn></msub><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>f</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac><mo>+</mo><mi>g</mi></mrow><annotation encoding=\\"application/x-tex\\">r_{new}=\\\\frac{D_{1}}{P_{0}(1-f)}+g</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"cost-of-goods-sold","name":"Cost of Goods Sold (Inventory Roll-Forward)"},"next":{"slug":"cost-of-preferred","name":"Cost of Preferred Stock"},"lesson":null,"total":522}')}}]);